public DEV_CleanUpTaskName getTaskName()
{
    ;
    return "Open return sales orders";
}

public Query getQuery()
{
    Query ret = new Query();

    QueryBuildDatasource    qbds = ret.addDataSource(tableNum(SalesTable));
    QueryBuildRange         qbr;

    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(SalesTable, SalesType));
    qbr.value(queryValue(SalesType::ReturnItem));
    qbr.status(RangeStatus::Locked);

    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(SalesTable, SalesStatus));
    qbr.value(queryValue(SalesStatus::Backorder));
    qbr.status(RangeStatus::Locked);

    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(SalesTable, SalesPoolId));

    return ret;
}

protected void updateQuery(Query _query, DEV_CleanupTaskSettingsQuery _settings)
{
    TransDateTime           cleanupdDateTime = _settings.getCleanupDateTime();
    QueryBuildDataSource    qbds = _query.dataSourceNo(1);
    QueryBuildRange         qbr;

    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(SalesTable, CreatedDateTime));
    qbr.value(SysQuery::range(dateNull(), cleanupdDateTime));
}
